-- drizzle cannot model: extensions, trigram GIN indexes, touch triggers, RLS policies, grants.
-- Sections (touch triggers, RLS) are the verbatim output of ../generate-platform-sql.ts.

CREATE EXTENSION IF NOT EXISTS pg_trgm;

-- Trigram GIN index backing candidate name search (Drizzle cannot model gin_trgm_ops).
CREATE INDEX IF NOT EXISTS candidate_name_trgm ON hiring.candidate USING gin (name gin_trgm_ops);

-- touch-updated-at: generated by @seta/shared-db buildTouchUpdatedAtFnSql/buildTouchTriggerSql
CREATE OR REPLACE FUNCTION hiring.tg_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END $$;
CREATE TRIGGER requisition_touch_updated_at
BEFORE UPDATE ON hiring.requisition
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER opening_touch_updated_at
BEFORE UPDATE ON hiring.opening
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER requisition_jd_section_touch_updated_at
BEFORE UPDATE ON hiring.requisition_jd_section
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER requisition_skill_touch_updated_at
BEFORE UPDATE ON hiring.requisition_skill
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER opening_close_reason_touch_updated_at
BEFORE UPDATE ON hiring.opening_close_reason
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER jd_template_touch_updated_at
BEFORE UPDATE ON hiring.jd_template
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER jd_template_section_touch_updated_at
BEFORE UPDATE ON hiring.jd_template_section
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER candidate_touch_updated_at
BEFORE UPDATE ON hiring.candidate
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER candidate_skill_touch_updated_at
BEFORE UPDATE ON hiring.candidate_skill
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER rejection_reason_touch_updated_at
BEFORE UPDATE ON hiring.rejection_reason
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();
CREATE TRIGGER application_touch_updated_at
BEFORE UPDATE ON hiring.application
FOR EACH ROW EXECUTE FUNCTION hiring.tg_touch_updated_at();

